```csharp
public static void OnPlayerUpdate(Player self) {
    if (self.Scene == null || self.Dead) {
        hasHoppedThisWall.Remove(self);
        return;
    }
    bool inCorner = IsInWallCorner(self);
    if (!inCorner) {
        // 离开墙角：重置本次事件，下一次贴墙上冲可以再触发
        hasHoppedThisWall.Remove(self);
        return;
    }
    if (!VerticalCornerBoostModule.Settings.Enabled) return;
    if (self.Speed.Y >= 0f) return;   // 正在下落，不是“向上运动”
    if (hasHoppedThisWall.ContainsKey(self)) return;  // 本次墙角已处理

    hasHoppedThisWall[self] = true;
    if (Math.Abs(self.Speed.Y - ClimbHopYSpeed) < 0.1f) return; // 原版已生效
    if (self.Speed.Y < ClimbHopYSpeed) return; // 已经更快 (CB/超级墙跳)，降速会违背“不改变翻越速度”
    self.Speed.Y = ClimbHopYSpeed;
}

private static bool IsInWallCorner(Player self) {
    Vector2 ahead = self.Position + Vector2.UnitX * (float)self.Facing * WallGlueDistance;
    if (!self.CollideCheck<Solid>(ahead)) return false;
    // 把判定盒贴墙并上移 Height + WallTopMargin：还有 Solid 就说明墙顶在头顶更高处，不是墙角
    return !self.CollideCheck<Solid>(ahead - Vector2.UnitY * (self.Height + WallTopMargin));
}

public static void Clear() => hasHoppedThisWall.Clear();
```

