		public ButtonExt(string label, string icon = null)
			: base(label)
		{
			Icon = icon;
		}

		public override void Render(Vector2 position, bool highlighted)
		{
			position += Offset;
			float num = Container.Alpha * Alpha;
			Color color;
			if (Disabled)
			{
				color = TextColorDisabled;
			}
			else
			{
				color = (highlighted ? Container.HighlightColor : TextColor);
			}
			Color color2 = color * num;
			Color strokeColor = Color.Black * (num * num * num);
			bool flag = Container.InnerContent == TextMenu.InnerContentMode.TwoColumn && !AlwaysCenter;
			Vector2 textPosition = position + (flag ? Vector2.Zero : new Vector2(Container.Width * 0.5f, 0f));
			Vector2 justify = (flag ? new Vector2(0f, 0.5f) : new Vector2(0.5f, 0.5f));
			Vector2 position2 = position;
			string icon = Icon;
			float? iconWidth = IconWidth;
			float inputHeight = Height();
			bool iconOutline = IconOutline;
			Color color3;
			if (Disabled)
			{
				color3 = Color.DarkSlateGray;
			}
			else
			{
				color3 = (highlighted ? Color.White : Color.LightSlateGray);
			}
			DrawIcon(position2, icon, iconWidth, inputHeight, iconOutline, color3 * num, ref textPosition);
			ActiveFont.DrawOutline(Label, textPosition, justify, Scale, color2, 2f, strokeColor);
		}
	}

