	/// <summary>
	///       A Slider optimized for large integer ranges.<br />
	///       Inherits directly from <see cref="T:Celeste.TextMenu.Item" /></summary>
	public class IntSlider : TextMenu.Item
	{
		public string Label;

		public int Index;

		public Action<int> OnValueChange;

		public int PreviousIndex;

		private float sine;

		private int lastDir;

		private int min;

		private int max;

		private float fastMoveTimer;

		/// <summary>
		///       Creates a new <see cref="T:Celeste.TextMenuExt.IntSlider" /></summary>
		/// <param name="label">Slider label</param>
		/// <param name="min">Minimum possible value</param>
		/// <param name="max">Maximum possible value</param>
		/// <param name="value">Initial value<br />Restricted between min and max</param>
		public IntSlider(string label, int min, int max, int value = 0)
		{
			Label = label;
			Selectable = true;
			this.min = min;
			this.max = max;
			Index = ((value < min) ? min : ((value > max) ? max : value));
		}

		/// <inheritdoc cref="M:Celeste.TextMenu.Option`1.Change(System.Action{`0})" />
		public IntSlider Change(Action<int> action)
		{
			OnValueChange = action;
			return this;
		}

		public override void Added()
		{
			Container.InnerContent = TextMenu.InnerContentMode.TwoColumn;
		}

		public override void LeftPressed()
		{
			if (Input.MenuLeft.Repeating)
			{
				fastMoveTimer += Engine.RawDeltaTime * 8f;
			}
			else
			{
				fastMoveTimer = 0f;
			}
			if (Index > min)
			{
				Audio.Play("event:/ui/main/button_toggle_off");
				PreviousIndex = Index;
				Index -= ((fastMoveTimer < 1f) ? 1 : ((fastMoveTimer < 3f) ? 10 : 25));
				Index = Math.Max(min, Index);
				lastDir = -1;
				ValueWiggler.Start();
				OnValueChange?.Invoke(Index);
			}
		}

		public override void RightPressed()
		{
			if (Input.MenuRight.Repeating)
			{
				fastMoveTimer += Engine.RawDeltaTime * 8f;
			}
			else
			{
				fastMoveTimer = 0f;
			}
			if (Index < max)
			{
				Audio.Play("event:/ui/main/button_toggle_on");
				PreviousIndex = Index;
				Index += ((fastMoveTimer < 1f) ? 1 : ((fastMoveTimer < 3f) ? 10 : 25));
				Index = Math.Min(max, Index);
				lastDir = 1;
				ValueWiggler.Start();
				OnValueChange?.Invoke(Index);
			}
		}

		public override void ConfirmPressed()
		{
			if (max - min == 1)
			{
				if (Index == min)
				{
					Audio.Play("event:/ui/main/button_toggle_on");
				}
				else
				{
					Audio.Play("event:/ui/main/button_toggle_off");
				}
				PreviousIndex = Index;
				lastDir = ((Index == min) ? 1 : (-1));
				Index = ((Index == min) ? max : min);
				ValueWiggler.Start();
				OnValueChange?.Invoke(Index);
			}
		}

		public override void Update()
		{
			sine += Engine.RawDeltaTime;
		}

		public override float LeftWidth()
		{
			return ActiveFont.Measure(Label).X + 32f;
		}

		public override float RightWidth()
		{
			return Calc.Max(0f, ActiveFont.Measure(max.ToString()).X, ActiveFont.Measure(min.ToString()).X, ActiveFont.Measure(Index.ToString()).X) + 120f;
		}

		public override float Height()
		{
			return ActiveFont.LineHeight;
		}

		public override void Render(Vector2 position, bool highlighted)
		{
			float alpha = Container.Alpha;
			Color strokeColor = Color.Black * (alpha * alpha * alpha);
			Color color = (Disabled ? Color.DarkSlateGray : ((highlighted ? Container.HighlightColor : Color.White) * alpha));
			ActiveFont.DrawOutline(Label, position, new Vector2(0f, 0.5f), Vector2.One, color, 2f, strokeColor);
			if (max - min > 0)
			{
				float num = RightWidth();
				ActiveFont.DrawOutline(Index.ToString(), position + new Vector2(Container.Width - num * 0.5f + (float)lastDir * ValueWiggler.Value * 8f, 0f), new Vector2(0.5f, 0.5f), Vector2.One * 0.8f, color, 2f, strokeColor);
				Vector2 vector = Vector2.UnitX * (float)(highlighted ? (Math.Sin(sine * 4f) * 4.0) : 0.0);
				Vector2 position2 = position + new Vector2(Container.Width - num + 40f + ((lastDir < 0) ? ((0f - ValueWiggler.Value) * 8f) : 0f), 0f) - ((Index > min) ? vector : Vector2.Zero);
				ActiveFont.DrawOutline("<", position2, new Vector2(0.5f, 0.5f), Vector2.One, (Index > min) ? color : (Color.DarkSlateGray * alpha), 2f, strokeColor);
				position2 = position + new Vector2(Container.Width - 40f + ((lastDir > 0) ? (ValueWiggler.Value * 8f) : 0f), 0f) + ((Index < max) ? vector : Vector2.Zero);
				ActiveFont.DrawOutline(">", position2, new Vector2(0.5f, 0.5f), Vector2.One, (Index < max) ? color : (Color.DarkSlateGray * alpha), 2f, strokeColor);
			}
		}
	}

	/// <summary>
	///   <see cref="T:Celeste.TextMenu.Item" /> that acts as a Submenu for other Items.
	///       </summary>
	public class SubMenu : TextMenu.Item
	{
		public string Label;

		private MTexture Icon;

		private List<TextMenu.Item> delayedAddItems;

		/// <inheritdoc cref="F:Celeste.TextMenu.Selection" />
		public int Selection;

		/// <inheritdoc cref="F:Celeste.TextMenu.ItemSpacing" />
		public float ItemSpacing;

		public float ItemIndent;

		/// <inheritdoc cref="F:Celeste.TextMenu.HighlightColor" />
		private Color HighlightColor;

		public string ConfirmSfx;

		public bool AlwaysCenter;

		public float LeftColumnWidth;

		public float RightColumnWidth;

		public bool Focused;

		public bool AutoScroll;

		public bool ItemsVisible;

		public SubMenu Parent;

		private bool enterOnSelect;

		private bool entering;

		private float ease;

		/// <inheritdoc cref="P:Celeste.TextMenu.Items" />
		public List<TextMenu.Item> Items { get; private set; }

		/// <inheritdoc cref="P:Celeste.TextMenu.Current" />
		public TextMenu.Item Current
		{
			get
			{
				if (Items.Count <= 0 || Selection < 0 || Selection >= Items.Count)
				{
					return null;
				}
				return Items[Selection];
			}
			set
			{
				Selection = Items.IndexOf(value);
			}
		}

		/// <inheritdoc cref="P:Celeste.TextMenu.FirstPossibleSelection" />
		public int FirstPossibleSelection
		{
			get
			{
				for (int i = 0; i < Items.Count; i++)
				{
					if (Items[i] != null && Items[i].Hoverable)
					{
						return i;
					}
				}
				return 0;
			}
		}

		/// <inheritdoc cref="P:Celeste.TextMenu.LastPossibleSelection" />
		public int LastPossibleSelection
		{
			get
			{
				for (int num = Items.Count - 1; num >= 0; num--)
				{
					if (Items[num] != null && Items[num].Hoverable)
					{
						return num;
					}
				}
				return 0;
			}
		}

		/// <inheritdoc cref="P:Celeste.TextMenu.ScrollTargetY" />
		public float ScrollTargetY
		{
			get
			{
				float min = (float)Engine.Height - 150f - Container.Height * Container.Justify.Y;
				float max = 150f + Container.Height * Container.Justify.Y;
				float num = ((Current != null) ? GetYOffsetOf(Current) : GetYOffsetOf(Items[Calc.Clamp(Selection, 0, Items.Count - 1)]));
				return Calc.Clamp((float)(Engine.Height / 2) + Container.Height * Container.Justify.Y - num, min, max);
			}
		}

		public float TitleHeight { get; private set; }

		public float MenuHeight { get; private set; }

		/// <summary>
		///       Create a new SubMenu.
		///       </summary>
		/// <param name="label" />
		/// <param name="enterOnSelect">Expand submenu when selected</param>
		public SubMenu(string label, bool enterOnSelect)
		{
			ConfirmSfx = "event:/ui/main/button_select";
			Label = label;
			Icon = GFX.Gui["downarrow"];
			Selectable = true;
			IncludeWidthInMeasurement = true;
			this.enterOnSelect = enterOnSelect;
			OnEnter = () =>
			{
				if (this.enterOnSelect)
				{
					ConfirmPressed();
				}
			};
			Items = new List<TextMenu.Item>();
			delayedAddItems = new List<TextMenu.Item>();
			Selection = -1;
			ItemSpacing = 4f;
			ItemIndent = 20f;
			HighlightColor = Color.White;
			RecalculateSize();
		}

		/// <summary>
		///       Add any non-submenu <see cref="T:Celeste.TextMenu.Item" /> to the Submenu
		///       </summary>
		/// <param name="item">Item to be added</param>
		/// <returns />
		public SubMenu Add(TextMenu.Item item)
		{
			if (Container != null)
			{
				Items.Add(item);
				item.Container = Container;
				if (item is SubMenu subMenu)
				{
					subMenu.Parent = this;
				}
				Container.Add(item.ValueWiggler = Wiggler.Create(0.25f, 3f));
				Container.Add(item.SelectWiggler = Wiggler.Create(0.25f, 3f));
				item.ValueWiggler.UseRawDeltaTime = (item.SelectWiggler.UseRawDeltaTime = true);
				RecalculateSize();
				item.Added();
				return this;
			}
			delayedAddItems.Add(item);
			return this;
		}

		/// <summary>
		///       Insert any non-submenu <see cref="T:Celeste.TextMenu.Item" /> into the Submenu at <paramref name="index" /></summary>
		/// <param name="index" />
		/// <param name="item">Item to be inserted</param>
		/// <returns />v
		public SubMenu Insert(int index, TextMenu.Item item)
		{
			if (Container != null)
			{
				Items.Insert(index, item);
				item.Container = Container;
				if (item is SubMenu subMenu)
				{
					subMenu.Parent = this;
				}
				Container.Add(item.ValueWiggler = Wiggler.Create(0.25f, 3f));
				Container.Add(item.SelectWiggler = Wiggler.Create(0.25f, 3f));
				item.ValueWiggler.UseRawDeltaTime = (item.SelectWiggler.UseRawDeltaTime = true);
				RecalculateSize();
				item.Added();
				return this;
			}
			delayedAddItems.Insert(index, item);
			return this;
		}

		public bool ContainsDelayedAddItem(TextMenu.Item item)
		{
			if (Container == null)
			{
				return delayedAddItems.Contains(item);
			}
			return false;
		}

		public SubMenu InsertDelayedAddItem(TextMenu.Item item, TextMenu.Item after)
		{
			if (Container == null && delayedAddItems.Contains(after))
			{
				delayedAddItems.Insert(delayedAddItems.IndexOf(after) + 1, item);
			}
			return this;
		}

		/// <summary>
		///       Remove any non-submenu <see cref="T:Celeste.TextMenu.Item" /> from the Submenu
		///       </summary>
		/// <param name="item">Item to be removed</param>
		/// <returns />v
		public SubMenu Remove(TextMenu.Item item)
		{
			if (Container != null)
			{
				if (!Items.Remove(item))
				{
					return this;
				}
				item.Container = null;
				if (item is SubMenu subMenu)
				{
					subMenu.Parent = null;
				}
				Container.Remove(item.ValueWiggler);
				Container.Remove(item.SelectWiggler);
				RecalculateSize();
				return this;
			}
			delayedAddItems.Remove(item);
			return this;
		}

		/// <inheritdoc cref="M:Celeste.TextMenu.Clear" />
		public void Clear()
		{
			Items = new List<TextMenu.Item>();
		}

		/// <inheritdoc cref="M:Celeste.TextMenu.IndexOf(Celeste.TextMenu.Item)" />
		public int IndexOf(TextMenu.Item item)
		{
			return Items.IndexOf(item);
		}

		/// <inheritdoc cref="M:Celeste.TextMenu.FirstSelection" />
		public void FirstSelection()
		{
			Selection = -1;
			MoveSelection(1);
		}

		/// <summary>
		///       Set the selection to the last possible <see cref="T:Celeste.TextMenu.Item" />.
		///       </summary>
		public void LastSelection()
		{
			Selection = Items.Count;
			MoveSelection(-1);
		}

		/// <inheritdoc cref="M:Celeste.TextMenu.MoveSelection(System.Int32,System.Boolean)" />
		public void MoveSelection(int direction, bool wiggle = false)
		{
			int selection = Selection;
			direction = Math.Sign(direction);
			int num = 0;
			foreach (TextMenu.Item item in Items)
			{
				if (item.Hoverable)
				{
					num++;
				}
			}
			do
			{
				Selection += direction;
				if (enterOnSelect && !entering && (Selection < 0 || Selection >= Items.Count))
				{
					Selection = selection;
					Exit();
					if (Parent == null)
					{
						Container.MoveSelection(direction, wiggle: true);
					}
					else
					{
						Parent.MoveSelection(direction, wiggle: true);
					}
					return;
				}
				if (num > 2)
				{
					if (Selection < 0)
					{
						Selection = Items.Count - 1;
					}
					else if (Selection >= Items.Count)
					{
						Selection = 0;
					}
				}
				else if (Selection < 0 || Selection > Items.Count - 1)
				{
					Selection = Calc.Clamp(Selection, 0, Items.Count - 1);
					break;
				}
			}
			while (!Current.Hoverable);
			if (!Current.Hoverable)
			{
				Selection = selection;
			}
			if (Selection != selection && Current != null)
			{
				if (selection >= 0 && selection < Items.Count && Items[selection] != null && Items[selection].OnLeave != null)
				{
					Items[selection].OnLeave();
				}
				Current.OnEnter?.Invoke();
				if (wiggle)
				{
					Audio.Play((direction > 0) ? "event:/ui/main/rollover_down" : "event:/ui/main/rollover_up");
					Current.SelectWiggler.Start();
				}
			}
		}

		/// <inheritdoc cref="M:Celeste.TextMenu.RecalculateSize" />
		public void RecalculateSize()
		{
			TitleHeight = ActiveFont.LineHeight;
			if (Items.Count < 1)
			{
				return;
			}
			float rightColumnWidth = (MenuHeight = 0f);
			LeftColumnWidth = (RightColumnWidth = rightColumnWidth);
			foreach (TextMenu.Item item in Items)
			{
				if (item.IncludeWidthInMeasurement)
				{
					LeftColumnWidth = Math.Max(LeftColumnWidth, item.LeftWidth());
				}
			}
			foreach (TextMenu.Item item2 in Items)
			{
				if (item2.IncludeWidthInMeasurement)
