			Vector2 vector2 = TextPadding * 4f;
			if (!char.IsControl(c) && ActiveFont.FontSize.Characters.ContainsKey(c) && (vector + vector2).X < Width)
			{
				Text += c;
				Audio.Play("event:/ui/main/rename_entry_char");
